glsl3.vert:
precision highp float;
uniform CCGlobal {
  mat4 cc_matView;
  mat4 cc_matViewInv;
  mat4 cc_matProj;
  mat4 cc_matProjInv;
  mat4 cc_matViewProj;
  mat4 cc_matViewProjInv;
  vec4 cc_cameraPos;
  vec4 cc_time;
  mediump vec4 cc_screenSize;
  mediump vec4 cc_screenScale;
};
uniform CCLocal {
  mat4 cc_matWorld;
  mat4 cc_matWorldIT;
};
in vec3 a_position;
in vec4 a_color;
in vec2 a_uv0;
out vec4 v_color;
out vec2 v_uv0;
void main () {
  vec4 pos = vec4(a_position, 1);
  #if CC_USE_MODEL
  pos = cc_matViewProj * cc_matWorld * pos;
  #else
  pos = cc_matViewProj * pos;
  #endif
  v_uv0 = a_uv0;
  v_color = a_color;
  gl_Position = pos;
}

glsl3.frag:
precision highp float;
#if USE_ALPHA_TEST
  uniform ALPHA_TEST {
    float alphaThreshold;
  };
#endif
void ALPHA_TEST (in vec4 color) {
  #if USE_ALPHA_TEST
      if (color.a < alphaThreshold) discard;
  #endif
}
void ALPHA_TEST (in float alpha) {
  #if USE_ALPHA_TEST
      if (alpha < alphaThreshold) discard;
  #endif
}
in vec4 v_color;
in vec2 v_uv0;
uniform sampler2D texture;
uniform Constant {
  vec4 baseColor;
  vec4 colorRange;
};
vec3 rgb2hsv(vec3 color) {
  float maxColor = max(max(color.r, color.g), color.b);
  float minColor = min(min(color.r, color.g), color.b);
  float delta = maxColor - minColor;
  float h = 0.0;
  float s = 0.0;
  float v = maxColor;
  if (maxColor != 0.0) {
    s = delta / maxColor;
  }
  if (delta != 0.0) {
    if (maxColor == color.r) {
      h = (color.g - color.b) / delta + (color.g < color.b ? 6.0 : 0.0);
    } else if (maxColor == color.g) {
      h = (color.b - color.r) / delta + 2.0;
    } else {
      h = (color.r - color.g) / delta + 4.0;
    }
    h /= 6.0;
  }
  return vec3(h, s, v);
}
vec3 hsv2rgb(vec3 hsv) {
  float h = hsv.x;
  float s = hsv.y;
  float v = hsv.z;
  if (s == 0.0) {
    return vec3(v);
  }
  h = fract(h) * 6.0;
  float i = floor(h);
  float f = h - i;
  float p = v * (1.0 - s);
  float q = v * (1.0 - s * f);
  float t = v * (1.0 - s * (1.0 - f));
  if (i == 0.0) {
    return vec3(v, t, p);
  } else if (i == 1.0) {
    return vec3(q, v, p);
  } else if (i == 2.0) {
    return vec3(p, v, t);
  } else if (i == 3.0) {
    return vec3(p, q, v);
  } else if (i == 4.0) {
    return vec3(t, p, v);
  } else {
    return vec3(v, p, q);
  }
}
void main () {
  vec4 o = vec4(1, 1, 1, 1);
  #if USE_TEXTURE
  vec4 texture_tmp = texture(texture, v_uv0);
  #if CC_USE_ALPHA_ATLAS_texture
      texture_tmp.a *= texture(texture, v_uv0 + vec2(0, 0.5)).r;
  #endif
  #if INPUT_IS_GAMMA
    o.rgb *= (texture_tmp.rgb * texture_tmp.rgb);
    o.a *= texture_tmp.a;
  #else
    o *= texture_tmp;
  #endif
  #endif
  o *= v_color;
  float saturationMin = clamp(colorRange.x, 0.0, 1.0);
  float saturationMax = clamp(colorRange.y, 0.0, 1.0);
  float brightnessMin = clamp(colorRange.z, 0.0, 1.0);
  float brightnessMax = clamp(colorRange.w, 0.0, 1.0);
  float brightness = mix(brightnessMax, brightnessMin, v_uv0.y);
  brightness = clamp(brightness, 0.0, 1.0);
  float saturation = mix(saturationMin, saturationMax, v_uv0.x);
  saturation = clamp(saturation, 0.0, 1.0);
  vec3 baseHsv = rgb2hsv(baseColor.rgb);
  vec3 hsv = vec3(baseHsv.x, saturation, brightness);
  o.rgb = hsv2rgb(hsv);
  ALPHA_TEST(o);
  gl_FragColor = o;
}

